import React from 'react';

import { showModal } from '@ui-kit/Modal';

import AddEquipModal from './AddEquipModal';
import { IEquip } from '../../../@types/equip.types';

export function editEquipModal(data: IEquip, onSave: (updatedItem: IEquip) => void) {
  showModal({
    children: (closeHandler: () => void) => (
      <AddEquipModal
        data={data}
        onSave={(newItem) => {
          onSave(newItem);
          closeHandler();
        }}
        onCancel={closeHandler}
      />
    ),
  });
}

export default { editEquipModal };
